            for (int i = 0; i < 60; i++)
            {
                string path = "Assets/_Game/Data/Missions/M" + (i + 1).ToString("000") + ".asset";
                var asset = AssetDatabase.LoadAssetAtPath<MissionData>(path);
                if (asset == null)
                {
                    asset = ScriptableObject.CreateInstance<MissionData>();
                    JsonUtility.FromJsonOverwrite(JsonUtility.ToJson(seeds.missions[i]), asset);
                    asset.SetEditorId("M" + (i + 1).ToString("000"));
                    asset.name = asset.Id;
                    AssetDatabase.CreateAsset(asset, path);
                }

                assets[i] = asset;
            }

            var catalog = AssetDatabase.LoadAssetAtPath<MissionCatalog>("Assets/_Game/Data/MainMissions.asset");
            if (catalog == null)
            {
                catalog = ScriptableObject.CreateInstance<MissionCatalog>();
                AssetDatabase.CreateAsset(catalog, "Assets/_Game/Data/MainMissions.asset");
            }

            catalog.missions = assets;
            catalog.chapterTitles = new[]
            {
